// SPDX-License-Identifier: MIT
pragma solidity ^0.8.27;

/**
 * @title VIONATrader
 * @notice On-chain CFD position manager for tokenized capital markets.
 *
 * Users deposit USDG as collateral to open long or short positions on
 * tokenized stocks. Profit/loss is settled in USDG at close using the
 * on-chain VIONAPriceFeed oracle.
 *
 * Integration with VIONA Shield:
 *   1. User calls ShieldedPool.spend() with recipient = this contract's
 *      pendingDeposit address, OR
 *   2. User unshields to wallet, approves USDG, calls openPosition() directly.
 *
 * Price precision: 6 decimals (1_000_000 = $1.00 USDG)
 * USDG decimals:   6
 */
interface IERC20 {
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function transfer(address to, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

interface IPriceFeed {
    function getPriceFresh(string calldata symbol) external view returns (uint256);
    function getPrice(string calldata symbol) external view returns (uint256 price, uint256 updatedAt);
}

contract VIONATrader {
    // ── Types ─────────────────────────────────────────────────────────────────

    struct Position {
        address  owner;
        string   symbol;
        uint256  usdgCollateral;  // USDG locked (6 decimals)
        uint256  entryPrice;      // price at open (6 decimals, i.e. $1 = 1_000_000)
        uint256  shares;          // collateral / entryPrice (18 decimals)
        bool     isLong;          // true = long, false = short
        uint256  openTime;
        bool     closed;
    }

    // ── Storage ───────────────────────────────────────────────────────────────

    address   public owner;
    IERC20    public usdg;
    IPriceFeed public priceFeed;

    uint256 public nextPositionId;
    mapping(uint256 => Position) public positions;

    /// @dev positions by owner for enumeration
    mapping(address => uint256[]) private _ownerPositions;

    /// Protocol fee: 0.1% of collateral at open
    uint256 public constant FEE_BPS = 10; // 10 / 10000 = 0.1%
    address public feeRecipient;

    // ── Events ────────────────────────────────────────────────────────────────

    event PositionOpened(
        uint256 indexed id,
        address indexed owner,
        string  symbol,
        bool    isLong,
        uint256 usdgCollateral,
        uint256 entryPrice,
        uint256 shares
    );

    event PositionClosed(
        uint256 indexed id,
        address indexed owner,
        string  symbol,
        bool    isLong,
        uint256 entryPrice,
        uint256 exitPrice,
        int256  pnl,
        uint256 usdgReturned
    );

    event OwnershipTransferred(address indexed prev, address indexed next);

    // ── Errors ────────────────────────────────────────────────────────────────

    error NotOwner();
    error NotPositionOwner();
    error PositionAlreadyClosed();
    error ZeroAmount();
    error ZeroAddress();
    error TransferFailed();

    // ── Modifiers ─────────────────────────────────────────────────────────────

    modifier onlyOwner() {
        if (msg.sender != owner) revert NotOwner();
        _;
    }

    // ── Constructor ───────────────────────────────────────────────────────────

    constructor(address _usdg, address _priceFeed, address _feeRecipient) {
        if (_usdg == address(0) || _priceFeed == address(0)) revert ZeroAddress();
        owner        = msg.sender;
        usdg         = IERC20(_usdg);
        priceFeed    = IPriceFeed(_priceFeed);
        feeRecipient = _feeRecipient == address(0) ? msg.sender : _feeRecipient;
    }

    function transferOwnership(address newOwner) external onlyOwner {
        if (newOwner == address(0)) revert ZeroAddress();
        emit OwnershipTransferred(owner, newOwner);
        owner = newOwner;
    }

    function setPriceFeed(address _priceFeed) external onlyOwner {
        if (_priceFeed == address(0)) revert ZeroAddress();
        priceFeed = IPriceFeed(_priceFeed);
    }

    function setFeeRecipient(address _feeRecipient) external onlyOwner {
        if (_feeRecipient == address(0)) revert ZeroAddress();
        feeRecipient = _feeRecipient;
    }

    // ── Core trading ──────────────────────────────────────────────────────────

    /**
     * @notice Open a leveraged position.
     * @param symbol        Ticker symbol, e.g. "AAPL"
     * @param usdgAmount    Amount of USDG to use as collateral (6 decimals)
     * @param isLong        True = long (profit when price rises), false = short
     * @return positionId   ID of the newly opened position
     */
    function openPosition(
        string calldata symbol,
        uint256 usdgAmount,
        bool    isLong
    ) external returns (uint256 positionId) {
        if (usdgAmount == 0) revert ZeroAmount();

        // Pull USDG from caller
        bool ok = usdg.transferFrom(msg.sender, address(this), usdgAmount);
        if (!ok) revert TransferFailed();

        // Deduct protocol fee
        uint256 fee       = (usdgAmount * FEE_BPS) / 10_000;
        uint256 collateral = usdgAmount - fee;

        // Pay fee to feeRecipient
        if (fee > 0 && feeRecipient != address(0)) {
            usdg.transfer(feeRecipient, fee);
        }

        // Get current price (reverts if stale)
        uint256 entryPrice = priceFeed.getPriceFresh(symbol);

        // Compute shares with 18-decimal precision
        // shares = collateral(6dec) * 1e18 / entryPrice(6dec)
        uint256 shares = (collateral * 1e18) / entryPrice;

        positionId = nextPositionId++;

        positions[positionId] = Position({
            owner:          msg.sender,
            symbol:         symbol,
            usdgCollateral: collateral,
            entryPrice:     entryPrice,
            shares:         shares,
            isLong:         isLong,
            openTime:       block.timestamp,
            closed:         false
        });

        _ownerPositions[msg.sender].push(positionId);

        emit PositionOpened(positionId, msg.sender, symbol, isLong, collateral, entryPrice, shares);
    }

    /**
     * @notice Close an open position and settle P&L in USDG.
     * @param positionId  The position to close.
     */
    function closePosition(uint256 positionId) external {
        Position storage pos = positions[positionId];
        if (pos.owner != msg.sender)  revert NotPositionOwner();
        if (pos.closed)               revert PositionAlreadyClosed();

        // Get exit price (allow stale on close so user can always exit)
        (uint256 exitPrice,) = priceFeed.getPrice(pos.symbol);
        if (exitPrice == 0) exitPrice = pos.entryPrice; // fallback: no change

        // P&L = shares * (exitPrice - entryPrice) [in USDG 6-dec]
        // shares is 18-decimal; prices are 6-decimal
        // pnl(6dec) = shares(18dec) * priceDelta(6dec) / 1e18
        int256 priceDelta = int256(exitPrice) - int256(pos.entryPrice);
        int256 rawPnl     = (int256(pos.shares) * priceDelta) / int256(1e18);
        int256 pnl        = pos.isLong ? rawPnl : -rawPnl;

        uint256 usdgReturned;
        if (pnl >= 0) {
            usdgReturned = pos.usdgCollateral + uint256(pnl);
        } else {
            uint256 loss = uint256(-pnl);
            usdgReturned = loss >= pos.usdgCollateral ? 0 : pos.usdgCollateral - loss;
        }

        pos.closed = true;

        if (usdgReturned > 0) {
            bool ok = usdg.transfer(msg.sender, usdgReturned);
            if (!ok) revert TransferFailed();
        }

        emit PositionClosed(
            positionId, msg.sender, pos.symbol, pos.isLong,
            pos.entryPrice, exitPrice, pnl, usdgReturned
        );
    }

    // ── View helpers ──────────────────────────────────────────────────────────

    /// @notice List all position IDs for an owner.
    function getPositionIds(address _owner) external view returns (uint256[] memory) {
        return _ownerPositions[_owner];
    }

    /// @notice Compute unrealised P&L for an open position (view, no revert).
    function unrealisedPnl(uint256 positionId)
        external
        view
        returns (int256 pnl, uint256 currentPrice)
    {
        Position storage pos = positions[positionId];
        if (pos.closed) return (0, 0);

        (currentPrice,) = priceFeed.getPrice(pos.symbol);
        if (currentPrice == 0) currentPrice = pos.entryPrice;

        int256 priceDelta = int256(currentPrice) - int256(pos.entryPrice);
        int256 rawPnl     = (int256(pos.shares) * priceDelta) / int256(1e18);
        pnl               = pos.isLong ? rawPnl : -rawPnl;
    }

    /// @notice Withdraw any accidental USDG sent directly to this contract.
    function rescueUSDG(uint256 amount) external onlyOwner {
        usdg.transfer(owner, amount);
    }
}

